#!/bin/bash
# Jev arms on GTA (t1 split, Qwen2.5-7B): read_arith + count_arith without search, then web_fact with search; one session per lane
: "${LG:?}" "${TG:?}" "${JB:?}"; M=/datasets/omni_pretraining/gta2/models/Qwen2.5-7B-Instruct
API=0 MODEL=$M TYPES=read_arith,count_arith SPLIT=t1 FRESH=jv ARMS=full,jevA,jevB,jevC GTA_EXTRA_MENUS="jevA=/datasets/omni_pretraining/gta2/results/jev/menus_A_{type}.json,jevB=/datasets/omni_pretraining/gta2/results/jev/menus_B_{type}.json,jevC=/datasets/omni_pretraining/gta2/results/jev/menus_C_{type}.json" TAG=jv_7b MENU_TAG=7b GTA_OBS_ROLE=user LGPU=$LG TGPU=$TG LPORT=8961 TPORT=16811 PPORT=16911 JOB=$JB bash /datasets/omni_pretraining/gta2/scripts_extra/gta_jev_lane.sh
API=1 MODEL=$M TYPES=web_fact SPLIT=t1 FRESH=jvw ARMS=full,jevA,jevB,jevC GTA_EXTRA_MENUS="jevA=/datasets/omni_pretraining/gta2/results/jev/menus_A_{type}.json,jevB=/datasets/omni_pretraining/gta2/results/jev/menus_B_{type}.json,jevC=/datasets/omni_pretraining/gta2/results/jev/menus_C_{type}.json" GTA_TRAJ_SFX=_api TAG=jvw_7b MENU_TAG=7b GTA_OBS_ROLE=user LGPU=$LG TGPU=$TG LPORT=8962 TPORT=16812 PPORT=16912 JOB=$JB bash /datasets/omni_pretraining/gta2/scripts_extra/gta_jev_lane.sh
